package net.lanbridge.android;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.io.*;

/** SMS diagnostics and log UI acceptance, on the explicit debug emulator only. */
public final class ParcelDebugInstrumentation extends Instrumentation {
    private Bundle args;private MainActivity activity;private Throwable failure;private int checks;
    @Override public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
    private void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}
    private void main(Runnable action){runOnMainSync(()->{try{action.run();}catch(Throwable e){failure=e;}});if(failure!=null)throw new AssertionError(failure);waitForIdleSync();}
    private View find(View root,String text){if(root==null)return null;if(text.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())||root instanceof TextView&&text.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View found=find(((ViewGroup)root).getChildAt(i),text);if(found!=null)return found;}return null;}
    private Spinner thinking(View root){if(root instanceof Spinner&&"思考强度".contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return (Spinner)root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){Spinner found=thinking(((ViewGroup)root).getChildAt(i));if(found!=null)return found;}return null;}
    private View page(String id){return activity.getFragmentManager().findFragmentByTag(id).getView();}
    private void click(String label){for(int attempt=0;attempt<30;attempt++){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null)for(AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(label)){if(!label.contentEquals(node.getText()))continue;android.graphics.Rect bounds=new android.graphics.Rect();node.getBoundsInScreen(bounds);if(!bounds.isEmpty()){long now=SystemClock.uptimeMillis();getUiAutomation().injectInputEvent(MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,bounds.centerX(),bounds.centerY(),0),true);getUiAutomation().injectInputEvent(MotionEvent.obtain(now,now+60,MotionEvent.ACTION_UP,bounds.centerX(),bounds.centerY(),0),true);SystemClock.sleep(150);waitForIdleSync();return;}}SystemClock.sleep(100);}throw new AssertionError("Missing action "+label);}

    private void text(String label,String value){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();ArrayDeque<AccessibilityNodeInfo> queue=new ArrayDeque<>();queue.add(root);while(!queue.isEmpty()){AccessibilityNodeInfo node=queue.remove();if("android.widget.EditText".contentEquals(node.getClassName())&&label.contentEquals(node.getContentDescription()==null?"":node.getContentDescription())){Bundle b=new Bundle();b.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);check(node.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,b),"Set field "+label);waitForIdleSync();return;}for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo child=node.getChild(i);if(child!=null)queue.add(child);}}throw new AssertionError("Missing field "+label);}
    private void keywords(){main(()->{activity.show("parcel");find(page("parcel"),"取件设置").performClick();});click("短信快速过滤");}
    private void capture(String name)throws Exception{SystemClock.sleep(150);android.graphics.Bitmap bitmap=getUiAutomation().takeScreenshot();try(FileOutputStream stream=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"parcel-processing-"+name+".png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,stream);}bitmap.recycle();}
    private List<ParcelSms.Message> own(List<ParcelSms.Message> messages,String marker){List<ParcelSms.Message> result=new ArrayList<>();for(ParcelSms.Message message:messages)if(message.body.contains(marker))result.add(message);return result;}
    private void restore(SharedPreferences prefs,Map<String,?> values){SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> entry:values.entrySet()){Object value=entry.getValue();if(value instanceof Boolean)edit.putBoolean(entry.getKey(),(Boolean)value);else if(value instanceof String)edit.putString(entry.getKey(),(String)value);else if(value instanceof Integer)edit.putInt(entry.getKey(),(Integer)value);else if(value instanceof Long)edit.putLong(entry.getKey(),(Long)value);}edit.commit();}
    private boolean windowText(String text){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();return root!=null&&!root.findAccessibilityNodeInfosByText(text).isEmpty();}
    private void waitText(String text){for(int i=0;i<100;i++){if(windowText(text))return;SystemClock.sleep(100);}throw new AssertionError("Missing state "+text);}
    private void scanMenu(){main(()->find(page("parcel"),"添加取件信息").performClick());try{capture("menu-open");}catch(Exception e){throw new RuntimeException(e);}click("扫描短信");}
    @Override public void onStart(){Context context=getTargetContext();Bundle result=new Bundle();boolean passed=false;JSONObject oldAi=null;SharedPreferences filter=context.getSharedPreferences("parcel-sms-filter",0),reasoning=context.getSharedPreferences("parcel-reasoning",0),automatic=ParcelAutoReader.prefs(context);Map<String,?> oldFilter=filter.getAll(),oldReasoning=reasoning.getAll(),oldAuto=automatic.getAll();String marker=args.getString("marker"),code=args.getString("code");
        try{
            check(context.getPackageName().endsWith(".debug"),"Debug required");automatic.edit().putBoolean("enabled",false).commit();filter.edit().clear().commit();ParcelSmsFilter.save(context,true,code);reasoning.edit().clear().commit();AiSettings settings=new AiSettings(context);oldAi=settings.exportSnapshot();settings.importSnapshot(new JSONObject().put("format",AiConfigCodec.FORMAT).put("version",1).put("providers",new JSONArray()).put("roles",new JSONObject()).put("secrets",new JSONObject()),settings.revision());
            activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK).putExtra("page","parcel"));
            main(()->{try{ParcelFragment fragment=(ParcelFragment)activity.getFragmentManager().findFragmentByTag("parcel");for(String name:new String[]{"start","end"}){java.lang.reflect.Field field=ParcelFragment.class.getDeclaredField(name);field.setAccessible(true);field.set(fragment,java.time.LocalDate.now().minusDays(1));}java.lang.reflect.Field days=ParcelFragment.class.getDeclaredField("presetDays");days.setAccessible(true);days.setInt(fragment,1);}catch(Exception e){throw new RuntimeException(e);}});
            int readCount=ParcelSms.query(context,java.time.LocalDate.now().atStartOfDay(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli(),System.currentTimeMillis()+1000).size();
            scanMenu();check(windowText("结束日期："+java.time.LocalDate.now()),"Cached yesterday was not refreshed");click("仅检查读取");waitText("短信读取诊断");check(windowText("读取来源：系统收件箱"),"No provider evidence");check(windowText("待AI=1"),"Diagnostic did not find the fcbox SMS");check(windowText("过滤="+(readCount-1)),"OTP filtering count incorrect");capture("diagnostic");click("查看日志");waitText("待AI=1");click("复制日志");ClipboardManager clipboard=(ClipboardManager)context.getSystemService(Context.CLIPBOARD_SERVICE);String logs=clipboard.getPrimaryClip().getItemAt(0).getText().toString();check(logs.contains("短信扫描")&&logs.contains("读取="+readCount),"No usable read logs");check(!logs.contains(code)&&!logs.contains("fcbox.com")&&!logs.contains("验证码889900"),"Logs leaked SMS content");capture("logs");click("关闭");
            long now=System.currentTimeMillis();List<ParcelSms.Message> raw=own(ParcelSms.query(context,now-3600000,now+1000),marker);check(raw.size()==2,"Two SMS provider fixtures required");try(ParcelStore store=new ParcelStore(context)){check(store.pendingSources(raw).size()==2,"Read-only diagnostic changed markers");}
            String provider=settings.saveProvider("debug-fixture","Debug fixture","openai",args.getString("endpoint"),"fixture-key");settings.saveMultimodal(provider,"debug-fixture");
            ParcelSms.Message arrival=null;for(ParcelSms.Message message:raw)if(message.body.contains(code))arrival=message;check(arrival!=null,"No arrival fixture");
            try(ParcelStore store=new ParcelStore(context)){store.ingest(List.of(arrival),List.of(new ParcelAi.Item(List.of(arrival.id),"","","","","",ParcelAi.OTHER,null)));ParcelScan scan=ParcelScan.read(context,java.time.LocalDate.now().atStartOfDay(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli(),System.currentTimeMillis(),store,false);check(scan.skipped==1&&scan.pending.isEmpty()&&scan.unlinked.size()==1,"Legacy no-record marker not diagnosed");check(scan.emptyReason().contains("没有关联快递记录")&&scan.summary().contains("已分析无关联记录=1"),"Unlinked reason not shown");}
            scanMenu();click("扫描并分析");waitText("重新识别未生成记录的短信？");click("取消");try(ParcelStore store=new ParcelStore(context)){check(store.pendingSources(List.of(arrival),true).size()==1,"Cancel changed retry markers");}
            scanMenu();click("扫描并分析");waitText("重新识别未生成记录的短信？");click("重新识别");waitText("取件码："+code);String parcelId=null;
            try(ParcelStore store=new ParcelStore(context)){for(ParcelStore.Parcel p:store.list(false,"address"))if(p.code.equals(code))parcelId=p.id;check(parcelId!=null,"Strict fallback did not recover the parcel");ParcelStore.SourceSelection selected=store.selectSources(List.of(arrival,arrival),true);check(selected.waiting==1&&selected.duplicates==1&&selected.unlinked.isEmpty()&&selected.pending.isEmpty(),"Existing pending parcel selected again");}
            scanMenu();click("扫描并分析");waitText("已有待取记录 1 条");check(!windowText("重新识别未生成记录的短信？"),"Existing parcel offered for retry");
            try(ParcelStore store=new ParcelStore(context)){store.setCollected(parcelId,true);ParcelStore.SourceSelection selected=store.selectSources(List.of(arrival),true);check(selected.archived==1&&selected.pending.isEmpty(),"Archived source selected again");}
            scanMenu();click("扫描并分析");waitText("归档记录 1 条");
            main(()->activity.show("settings"));click("运行日志");waitText("AI结果");click("复制日志");logs=clipboard.getPrimaryClip().getItemAt(0).getText().toString();check(logs.contains("非快递=1")&&logs.contains("规则补救")&&logs.contains("改为待取=1")&&logs.contains("已有归档记录=1")&&logs.contains("快递入库"),"Logs miss AI decisions or ingestion");check(!logs.contains(code)&&!logs.contains("fixture-key"),"Logs contain private code/key");capture("ai-result");click("关闭");
            result.putString("stream","PASS: "+checks+" debug checks: rolling date, config-free read diagnosis, real manual scan, handled/retry paths, log entry and copy, privacy and AI classifications\n");passed=true;
        }catch(Throwable e){result.putString("stream",android.util.Log.getStackTraceString(e));}
        finally{try{if(marker!=null)try(ParcelStore store=new ParcelStore(context)){android.database.sqlite.SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{for(ParcelStore.Parcel parcel:store.list(false,"address"))if(parcel.sources.size()==1&&parcel.sources.get(0).body.contains(marker)){String fingerprint=parcel.sources.get(0).fingerprint;db.delete("parcels","id=?",new String[]{parcel.id});db.delete("sources","fingerprint=?",new String[]{fingerprint});db.delete("processed","fingerprint=?",new String[]{fingerprint});}db.setTransactionSuccessful();}finally{db.endTransaction();}}if(oldAi!=null)new AiSettings(context).importSnapshot(oldAi,new AiSettings(context).revision());restore(filter,oldFilter);restore(reasoning,oldReasoning);restore(automatic,oldAuto);if(activity!=null){failure=null;main(()->activity.finish());}}catch(Exception e){passed=false;result.putString("stream","Cleanup failed: "+e.getClass().getSimpleName());}}
        finish(passed?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
}
